const updateCardSchedule = `-- name: UpdateCardSchedule :execrows
UPDATE card_schedules
SET enabled = $1,
    frequency = $2,
    day_of_week = $3,
    day_of_month = $4,
    time_of_day = $5,
    interval_minutes = $6,
    timezone = $7,
    next_trigger_at = $8,
    updated_at = now()
WHERE workspace_id = $9
  AND card_id = $10
  AND id = $11
`

type UpdateCardScheduleParams struct {
	Enabled         bool               `json:"enabled"`
	Frequency       string             `json:"frequency"`
	DayOfWeek       pgtype.Int2        `json:"day_of_week"`
	DayOfMonth      pgtype.Int2        `json:"day_of_month"`
	TimeOfDay       pgtype.Time        `json:"time_of_day"`
	IntervalMinutes pgtype.Int4        `json:"interval_minutes"`
	Timezone        string             `json:"timezone"`
	NextTriggerAt   pgtype.Timestamptz `json:"next_trigger_at"`
	WorkspaceID     uuid.UUID          `json:"workspace_id"`
	CardID          uuid.UUID          `json:"card_id"`
	ID              uuid.UUID          `json:"id"`
}

func (q *Queries) UpdateCardSchedule(ctx context.Context, arg UpdateCardScheduleParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateCardSchedule,
		arg.Enabled,
		arg.Frequency,
		arg.DayOfWeek,
		arg.DayOfMonth,
		arg.TimeOfDay,
		arg.IntervalMinutes,
		arg.Timezone,
		arg.NextTriggerAt,
		arg.WorkspaceID,
		arg.CardID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

